    /// <summary>查这张卡自带的关键字与重甲；查不到返回空 / 0。</summary>
    public static (string[] Keywords, int HeavyArmor) Get(string cardName)
    {
        if (cardName.Length > 0 && ByCard.TryGetValue(cardName, out var hit))
        {
            return hit;
        }

        string baseName = CardDatabase.ResolveBaseName(cardName);
        if (!string.Equals(baseName, cardName, StringComparison.Ordinal)
            && ByCard.TryGetValue(baseName, out var fallback))
        {
            return fallback;
        }

        return (Array.Empty<string>(), 0);
    }
}
